import java.io.IOException;

public class HttpConnectionTest {

    @Test
    public void connectMethodConnectsToUrl() throws IOException {
        Connection connection = HttpConnection.connect("http://www.example.com");
        assertTrue(connection.url().getHost().equals("www.example.com"));
    }

    @Test
    public void connectMethodConnectsToUrlWithProxy() throws IOException {
        Connection connection = HttpConnection.connect("http://www.example.com", new Proxy(Proxy.Type.HTTP, 8080));
        assertTrue(connection.proxy().equals(new Proxy(Proxy.Type.HTTP, 8080)));
    }

    @Test
    public void urlMethodSetsUrl() {
        Connection connection = HttpConnection.url("http://www.example.com");
        assertEquals("http://www.example.com", connection.url().getHost());
    }

    @Test
    public void urlMethodSetsUrlAsString() {
        Connection connection = HttpConnection.url("http://www.example.com", 80);
        assertEquals("http://www.example.com", connection.url().getHost());
    }

    @Test
    public void proxyMethodSetsProxy() throws IOException {
        Connection connection = HttpConnection.proxy(new Proxy(Proxy.Type.HTTP, 8080));
        assertTrue(connection.proxy().equals(new Proxy(Proxy.Type.HTTP, 8080)));
    }

    @Test
    public void proxyMethodSetsProxyAsString() throws IOException {
        Connection connection = HttpConnection.proxy("www.example.com", 80);
        assertEquals("http://www.example.com", connection.url().getHost());
    }

    @Test
    public void connectReturnsNewInstance() {
        String url1 = "http://www.example.com";
        String url2 = "http://www.example2.com";

        Connection connection1 = HttpConnection.connect(url1);
        Connection connection2 = HttpConnection.connect(url2);

        assertNotSame(connection1, connection2);
    }

    @Test
    public void newRequestReturnsNewInstance() {
        String url = "http://www.example.com";
        Connection connection = HttpConnection.url(url).newRequest();

        assertNotNull(connection.request());
    }

    @Test
    public void executeThrowsIOException() throws IOException {
        try {
            HttpConnection.connect("http://www.example.com").execute();
            fail("Expected IOException");
        } catch (IOException e) {
            // expected
        }
    }

    @Test
    public void getReturnsDocument() throws IOException {
        Connection connection = HttpConnection.connect("http://www.example.com");
        Document document = connection.get();

        assertNotNull(document);
        assertTrue(document.title().length() > 0);
    }

    @Test
    public void postReturnsDocument() throws IOException {
        Connection connection = HttpConnection.connect("http://www.example.com").method(Connection.Method.POST).requestBody("example body");
        Document document = connection.post();

        assertNotNull(document);
        assertTrue(document.title().length() > 0);
    }
